class Solution:
    def minDifference(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        ans = []
        for l, r in queries:
            vals = sorted(set(nums[l:r + 1]))
            if len(vals) < 2:
                ans.append(-1)
            else:
                ans.append(min(vals[i + 1] - vals[i] for i in range(len(vals) - 1)))
        return ans

