var minDifference = function(nums, queries) {
    const pos = new Map();
    nums.forEach((x, i) => {
        if (!pos.has(x)) pos.set(x, []);
        pos.get(x).push(i);
    });
    const ans = [];
    for (const [l, r] of queries) {
        let prev = -1, best = Infinity;
        for (let v = 1; v <= 100; v++) {
            const lst = pos.get(v);
            if (!lst) continue;
            let lo = 0, hi = lst.length;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (lst[mid] < l) lo = mid + 1;
                else hi = mid;
            }
            if (lo < lst.length && lst[lo] <= r) {
                if (prev !== -1) best = Math.min(best, v - prev);
                prev = v;
            }
        }
        ans.push(best === Infinity ? -1 : best);
    }
    return ans;
};
